/**
 * Formatea la frase de edad para inyectar en las plantillas HTML
 * E.g.: "18 años" -> "mayores de 18 a&ntilde;os"
 *       "1 año" -> "mayores de 1 a&ntilde;o"
 *       "Todas las edades" -> "de todas las edades"
 */
export function formatAgePhrase(age: string): string {
  if (!age) return "mayores de 18 a&ntilde;os";
  const clean = age.trim().toLowerCase();
  if (clean.includes("toda")) {
    return "de todas las edades";
  }
  if (clean.includes("1 año") || clean === "1 año" || clean === "1 a&ntilde;o" || clean === "1 ano") {
    return "mayores de 1 a&ntilde;o";
  }
  const normalized = age.replace(/años|a&ntilde;os|anos/gi, "a&ntilde;os");
  if (normalized.startsWith("mayores de")) {
    return normalized;
  }
  return `mayores de ${normalized}`;
}

/**
 * Reemplaza de forma segura la edad en el bloque HTML de Descripción o Términos y Condiciones
 */
export function replaceAgeInHtml(html: string, newAge: string): string {
  if (!html) return html;
  const agePhrase = formatAgePhrase(newAge);
  
  // 1. Patrón principal en descripción / términos:
  // "Solo se permitirá el acceso a personas... <strong>...</strong>"
  const regexPrincipal = /(Solo se permitir(?:&aacute;|á) el acceso a personas(?:&nbsp;|\s)*<strong[^>]*>)(.*?)(<\/strong>)/gi;
  if (regexPrincipal.test(html)) {
    return html.replace(regexPrincipal, `$1${agePhrase}$3`);
  }
  
  // 2. Patrón alternativo común con <strong>:
  const regexAlt = /(<strong[^>]*>)(?:mayores de \d+ (?:a&ntilde;os|años|a&ntilde;o|año)|de todas las edades|todas las edades)(<\/strong>)/gi;
  if (regexAlt.test(html)) {
    return html.replace(regexAlt, `$1${agePhrase}$2`);
  }

  return html;
}

/**
 * Genera la descripción oficial inyectando la edad deseada
 */
export function getEventDescription(age: string = DEFAULT_MIN_AGE): string {
  return replaceAgeInHtml(DEFAULT_EVENT_DESCRIPTION, age);
}

/**
 * Genera los términos oficiales inyectando la edad deseada
 */
export function getEventTerms(age: string = DEFAULT_MIN_AGE): string {
  return replaceAgeInHtml(DEFAULT_EVENT_TERMS, age);
}
